@startebnf
title Command
command = ("get" | "put"), name, [ "--force" ];
name = letter, { letter | digit };
letter = ? alphabetic ?;
digit = ? decimal digit ?;
@endebnf

@startebnf
title Nested lists
list = "[", [ item, { ",", item } ], "]";
item = word | list;
word = letter, { letter };
letter = ? alphabetic ?;
@endebnf

@startebnf
title Protocol line
message = verb, " ", path, [ "?", query ];
verb = "GET" | "POST" | "DELETE";
path = "/", name, { "/", name };
query = name, "=", name, { "&", name, "=", name };
name = ? nonempty text ?;
@endebnf
